assignments.referenceSolution:
Approach: `run` opens one `AsyncExitStack` per call and creates a fresh cache. `_kwargs` walks the signature, delegating `Depends` defaults to `_resolve`, which checks for cycles, consults the cache, swaps in an override if present, resolves the callable's own parameters recursively and invokes it. Async generator functions are entered as async context managers on the stack, which gives reverse-order teardown and exception delivery. Because the stack is closed in `run`'s `async with`, teardown happens after the endpoint returns or raises.

**`di_mini.py`**

```python
from __future__ import annotations

import inspect
from collections.abc import Callable
from contextlib import AsyncExitStack, asynccontextmanager
from typing import Any


class Depends:
    def __init__(self, dependency: Callable[..., Any], *, use_cache: bool = True) -> None:
        self.dependency = dependency
        self.use_cache = use_cache


class CircularDependencyError(Exception):
    pass


class Resolver:
    def __init__(self, overrides: dict[Callable[..., Any], Callable[..., Any]] | None = None) -> None:
        self._overrides = overrides or {}

    async def run(self, endpoint: Callable[..., Any], **values: Any) -> Any:
        cache: dict[Callable[..., Any], Any] = {}
        async with AsyncExitStack() as stack:
            kwargs = await self._kwargs(endpoint, values, cache, stack, ())
            return await self._invoke(endpoint, kwargs, stack)

    async def _kwargs(
        self,
        fn: Callable[..., Any],
        values: dict[str, Any],
        cache: dict[Callable[..., Any], Any],
        stack: AsyncExitStack,
        path: tuple[Callable[..., Any], ...],
    ) -> dict[str, Any]:
        kwargs: dict[str, Any] = {}
        for name, param in inspect.signature(fn).parameters.items():
            if isinstance(param.default, Depends):
                kwargs[name] = await self._resolve(param.default, cache, stack, path)
            elif name in values:
                kwargs[name] = values[name]
            elif param.default is inspect.Parameter.empty:
                raise TypeError(f"missing value for parameter {name!r} of {fn.__name__}")
        return kwargs

    async def _resolve(
        self,
        dep: Depends,
        cache: dict[Callable[..., Any], Any],
        stack: AsyncExitStack,
        path: tuple[Callable[..., Any], ...],
    ) -> Any:
        original = dep.dependency
        if original in path:
            raise CircularDependencyError(" -> ".join(f.__name__ for f in (*path, original)))
        if dep.use_cache and original in cache:
            return cache[original]
        actual = self._overrides.get(original, original)
        kwargs = await self._kwargs(actual, {}, cache, stack, (*path, original))
        value = await self._invoke(actual, kwargs, stack)
        cache.setdefault(original, value)
        return value

    @staticmethod
    async def _invoke(fn: Callable[..., Any], kwargs: dict[str, Any], stack: AsyncExitStack) -> Any:
        if inspect.isasyncgenfunction(fn):
            return await stack.enter_async_context(asynccontextmanager(fn)(**kwargs))
        result = fn(**kwargs)
        if inspect.isawaitable(result):
            result = await result
        return result
```

**`test_di_mini.py`**

```python
import asyncio

import pytest

from di_mini import CircularDependencyError, Depends, Resolver


def test_cache_and_use_cache():
    calls = []

    def settings():
        calls.append("settings")
        return {"env": "test"}

    def a(s=Depends(settings)):
        return s

    def b(s=Depends(settings, use_cache=False)):
        return s

    async def endpoint(x=Depends(a), y=Depends(b), z=Depends(settings)):
        return (x, y, z)

    asyncio.run(Resolver().run(endpoint))
    assert calls == ["settings", "settings"]


def test_teardown_order_and_error():
    log = []

    async def pool():
        log.append("pool+")
        try:
            yield "pool"
        finally:
            log.append("pool-")

    async def session(p=Depends(pool)):
        log.append("session+")
        try:
            yield f"session({p})"
        except ValueError:
            log.append("rollback")
            raise
        finally:
            log.append("session-")

    async def endpoint(s=Depends(session), fail: bool = False):
        log.append("handler")
        if fail:
            raise ValueError("boom")
        return s

    assert asyncio.run(Resolver().run(endpoint)) == "session(pool)"
    assert log == ["pool+", "session+", "handler", "session-", "pool-"]
    log.clear()
    with pytest.raises(ValueError):
        asyncio.run(Resolver().run(endpoint, fail=True))
    assert log == ["pool+", "session+", "handler", "rollback", "session-", "pool-"]


def test_overrides_and_values():
    def get_repo():
        return "real"

    async def service(repo=Depends(get_repo)):
        return repo.upper()

    async def endpoint(svc=Depends(service), ride_id: str = "r0"):
        return (svc, ride_id)

    assert asyncio.run(Resolver().run(endpoint, ride_id="r9")) == ("REAL", "r9")
    assert asyncio.run(Resolver({get_repo: lambda: "fake"}).run(endpoint)) == ("FAKE", "r0")


def test_cycle_is_reported():
    def a(x=None):
        return x

    def b(y=Depends(a)):
        return y

    a.__defaults__ = (Depends(b),)

    def endpoint(v=Depends(a)):
        return v

    with pytest.raises(CircularDependencyError, match="a -> b -> a"):
        asyncio.run(Resolver().run(endpoint))


def test_missing_value_raises_type_error():
    def endpoint(ride_id: str):
        return ride_id

    with pytest.raises(TypeError, match="ride_id"):
        asyncio.run(Resolver().run(endpoint))
